package com.example.saasguide.communication.application.domain;
import com.example.saasguide.communication.application.client.EligibilityResult; import com.example.saasguide.communication.application.client.EligibilityRetryClient; import com.example.saasguide.communication.application.context.ServiceRequestContext; import com.example.saasguide.communication.application.error.ApplicationNotFoundException; import com.example.saasguide.communication.application.error.EligibilityDeniedException; import java.util.UUID; import org.springframework.stereotype.Service;
@Service public class ApplicationService { private final EligibilityRetryClient client; private final InMemoryApplicationRepository repository; public ApplicationService(EligibilityRetryClient c,InMemoryApplicationRepository r){client=c;repository=r;} public ApplicationRecord create(String applicantId,ServiceRequestContext context){EligibilityResult result=client.check(applicantId,context); if(!result.eligible())throw new EligibilityDeniedException(); ApplicationRecord record=new ApplicationRecord(UUID.randomUUID().toString(),applicantId,context.tenantId(),"ACCEPTED"); repository.save(record); return record;} public ApplicationRecord get(String id,ServiceRequestContext context){return repository.find(id,context.tenantId()).orElseThrow(ApplicationNotFoundException::new);} }
